// Publishes articles on schedule and serves the live article list, sitemap, RSS and llms.txt.
// The data file is generated by `npm run build` (site/build.mjs) before Netlify bundles this.
import { articles, staticUrls } from '../../site/.generated/data.mjs';
import { handle } from '../../site/gate.mjs';

export default (request, context) =>
  handle(request, new Date(), () => context.next(), { articles, staticUrls });

export const config = {
  path: ['/articles', '/articles/*', '/sitemap.xml', '/feed.xml', '/llms.txt'],
};
